#[cfg(test)]
mod tests {
    use rigorix_engine::effect_commitment::domain::{CommitmentError, EffectRecordId, EffectState};

    #[test]
    fn test_commitmenterror_is_defined() {
        let id = EffectRecordId::new();

        let settled = CommitmentError::AlreadySettled {
            record_id: id,
            state: EffectState::Committed,
        };
        assert_eq!(settled.code(), "already_settled");
        assert!(!settled.is_retriable());
        assert!(settled.to_string().contains(&id.to_string()));

        let not_ambiguous = CommitmentError::NotAmbiguous {
            record_id: id,
            state: EffectState::Dispatched,
        };
        assert_eq!(not_ambiguous.code(), "not_ambiguous");

        let unauthorized = CommitmentError::UnauthorizedResolver {
            resolver_id: "agent".to_string(),
            reason: "F4".to_string(),
        };
        assert_eq!(unauthorized.code(), "unauthorized_resolver");

        let missing = CommitmentError::EvidenceMissing { record_id: id };
        assert_eq!(missing.code(), "evidence_missing");
    }

    #[test]
    fn test_commitmenterror_interacts_with_none() {
        // Only transport faults are retriable; a wrong state is not fixed by
        // retrying the identical request.
        let unavailable = CommitmentError::Unavailable {
            detail: "connection refused".to_string(),
        };
        assert_eq!(unavailable.code(), "unavailable");
        assert!(unavailable.is_retriable());
        assert!(unavailable.is_unavailable());

        let contended = CommitmentError::Contended {
            record_id: None,
            detail: "lost the write race".to_string(),
        };
        assert_eq!(contended.code(), "contended");
        assert!(contended.is_retriable());
        assert!(!contended.is_unavailable());

        assert!(
            !CommitmentError::EvidenceMissing {
                record_id: EffectRecordId::new()
            }
            .is_retriable()
        );
    }
}
